import { test, expect } from '@playwright/test';

test.describe('Login Page - Invalid Password Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
  });

  test('should display error message when submitting wrong password', async ({ page }) => {
    // Locate and fill username field using getByLabel
    const usernameField = page.getByLabel('Username');
    await usernameField.fill('tomsmith');

    // Locate and fill password field using getByLabel
    const passwordField = page.getByLabel('Password');
    await passwordField.fill('wrongpassword');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /login/i });
    await submitButton.click();

    // Verify the user remains on the login page
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/login');

    // Verify the error flash banner is visible
    const errorBanner = page.locator('.flash.error');
    await expect(errorBanner).toBeVisible();

    // Verify the error message contains the expected text
    await expect(errorBanner).toContainText('Your password is invalid!');
  });

  test('should not navigate away when password fails validation', async ({ page }) => {
    // Locate and fill username field using getByLabel
    const usernameField = page.getByLabel('Username');
    await usernameField.fill('tomsmith');

    // Locate and fill password field with wrong password using getByLabel
    const passwordField = page.getByLabel('Password');
    await passwordField.fill('wrongpassword');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /login/i });
    await submitButton.click();

    // Verify the page URL has not changed
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/login');

    // Verify the error banner is visible
    const errorBanner = page.locator('.flash.error');
    await expect(errorBanner).toBeVisible();

    // Verify the error message is displayed
    await expect(errorBanner).toContainText('Your password is invalid!');

    // Verify the login form elements are still present and enabled
    await expect(usernameField).toBeVisible();
    await expect(passwordField).toBeVisible();
    await expect(submitButton).toBeVisible();
  });
});
